{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Ethinylestradiol, which shares the phenolic A ring and a C17 tertiary alcohol with the query, has an absolute oral bioavailability of 62% (55-70%) in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The closest-scoring analogue (estrone scaffold) is reported to have oral bioavailability of about 25-65%, supporting high systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Estetrol, another estradiol analogue, is reported to have high and dose-related oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Moxestrol, a 17α-ethynyl estradiol analogue, has an absolute oral bioavailability of 35% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Estradiol has only ~5% absolute oral bioavailability, but this low value is driven by rapid oxidation of the 17β-hydroxyl; the query's C17 is a tertiary alcohol lacking that metabolic liability, so this low-F evidence does not transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an estradiol-like steroid with a phenolic A ring and a C17 tertiary alcohol. Analogues with a metabolically blocked C17 (ethinylestradiol, moxestrol, estetrol) show oral bioavailability of 35-62%, well above 20%. Estradiol's low F (~5%) is due to oxidation of the 17β-hydroxyl, a liability absent in the query. Therefore, high oral bioavailability is predicted.",
  "evidence_gaps": [
    "No direct experimental F measurement for the exact query; prediction relies on analogues with modified D rings.",
    "The record for the closest analogue (C15) may refer to ethinylestradiol rather than estrone, adding uncertainty.",
    "The effect of the extra carbon bridge on metabolism and solubility is not directly covered by the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

